param([string]$Version)
# Generated by installgen (https://github.com/lovrozagar/installgen). Regenerate it with `installgen build`.
#
#   powershell -c "irm <url> | iex"                  the latest version
#   iex "& {$(irm <url>)} -Version 1.2.3"            a specific version
#
# Environment: MY_CLI_VERSION, MY_CLI_INSTALL_DIR, MY_CLI_NO_MODIFY_PATH=1, NO_COLOR.
# Windows PowerShell 5.1 and PowerShell 7+. Failures throw and leave the session open: under `irm | iex`,
# ending the script any other way would close the user's window.

& {
	$ErrorActionPreference = 'Stop'
	$ProgressPreference = 'SilentlyContinue'
	if ($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage') {
		throw "this installer needs PowerShell FullLanguage mode; this session runs in $($ExecutionContext.SessionState.LanguageMode) mode"
	}

	$name = 'my-cli'
	$baseUrl = 'https://github.com/acme/my-cli/releases'
	$latestUrl = 'https://github.com/acme/my-cli/releases/latest/download/version.txt'
	$defaultVersion = ''
	$tagPrefix = 'v'
	$modifyPath = $true
	$message = ''
	$shUrl = 'https://github.com/acme/my-cli/releases/latest/download/install.sh'
	$ps1Url = 'https://github.com/acme/my-cli/releases/latest/download/install.ps1'
	$platforms = @('windows/amd64', 'windows/arm64')

	$installDir = $env:MY_CLI_INSTALL_DIR
	if ($installDir) {
		$dirShown = $installDir
	} else {
		$installDir = [IO.Path]::Combine([string[]](@([Environment]::GetFolderPath('UserProfile')) + @('.my-cli', 'bin')))
		$dirShown = '~\.my-cli\bin'
	}
	if ($env:MY_CLI_NO_MODIFY_PATH) { $modifyPath = $false }
	$requested = if ($Version) { $Version } else { $env:MY_CLI_VERSION }

	# UI: color only on a real console; check glyphs only where the terminal renders them
	$tty = ($Host.Name -eq 'ConsoleHost') -and (-not [Console]::IsOutputRedirected)
	$useColor = $tty -and (-not $env:NO_COLOR)
	$unicode = [bool]($env:WT_SESSION -or $env:TERM_PROGRAM)
	$okGlyph = if ($unicode) { [string][char]0x2713 } else { '+' }
	$downGlyph = if ($unicode) { [string][char]0x2193 } else { 'v' }

	function Write-Row([string]$Glyph, [string]$Tint, [string]$Label, [string]$Value) {
		if ($useColor) { Write-Host -NoNewline -ForegroundColor $Tint $Glyph } else { Write-Host -NoNewline $Glyph }
		Write-Host (' {0,-10} {1}' -f $Label, $Value)
	}
	function Write-Ok([string]$Label, [string]$Value) { Write-Row -Glyph $okGlyph -Tint 'Green' -Label $Label -Value $Value }
	function Write-WarnRow([string]$Label, [string]$Value) { Write-Row -Glyph '!' -Tint 'Yellow' -Label $Label -Value $Value }
	function Write-Warn([string]$Text) {
		if ($useColor) { Write-Host -ForegroundColor Yellow "warning: $Text" } else { Write-Host "warning: $Text" }
	}
	function Fail([string]$Text) { throw "$name install failed: $Text" }

	function Save-WithProgress([string]$Url, [string]$Path, [string]$Label) {
		# a pty without a size reports 0 columns
		$width = 80
		try {
			$columns = [Console]::WindowWidth
			if ($columns -ge 20) { $width = $columns }
		} catch {
			Write-Verbose 'no console width; using 80 columns'
		}
		$request = [Net.HttpWebRequest]::Create($Url)
		if ($request.Proxy) { $request.Proxy.Credentials = [Net.CredentialCache]::DefaultNetworkCredentials }
		$response = $request.GetResponse()
		try {
			$total = $response.ContentLength
			$in = $response.GetResponseStream()
			$out = [IO.File]::Create($Path)
			try {
				$buffer = New-Object byte[] 65536
				$done = 0
				$last = [DateTime]::MinValue
				while ($true) {
					$read = $in.Read($buffer, 0, $buffer.Length)
					$now = [DateTime]::UtcNow
					if ($read -gt 0) {
						$out.Write($buffer, 0, $read)
						$done += $read
					}
					if ($read -le 0 -or ($now - $last).TotalMilliseconds -ge 100) {
						$last = $now
						if ($total -gt 0) {
							$bar = [Math]::Max(10, $width - $Label.Length - 12)
							$filled = [int][Math]::Floor($bar * $done / $total)
							$line = '{0} {1} [{2}{3}] {4,3}%' -f $downGlyph, $Label, ('#' * $filled), (' ' * ($bar - $filled)), [int](100 * $done / $total)
						} else {
							$line = '{0} {1} {2:N1} MB' -f $downGlyph, $Label, ($done / 1MB)
						}
						[Console]::Write("`r" + $line.PadRight($width - 1).Substring(0, $width - 1))
					}
					if ($read -le 0) { break }
				}
			} finally {
				$out.Dispose()
				$in.Dispose()
			}
		} finally {
			$response.Close()
			[Console]::Write("`r" + (' ' * ($width - 1)) + "`r")
		}
	}

	function Save-Url([string]$Url, [string]$Path, [string]$Label) {
		if ($Label -and $tty -and $useColor) {
			try {
				Save-WithProgress -Url $Url -Path $Path -Label $Label
				return
			} catch {
				Remove-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
			}
		}
		Invoke-WebRequest -UseBasicParsing -Uri $Url -OutFile $Path
	}

	Write-Host "$name installer"

	# Platform: the registry knows the real CPU, even from an emulated x64 PowerShell on ARM64
	$onWindows = ($PSVersionTable.PSEdition -ne 'Core') -or $IsWindows
	if ($onWindows) {
		$cpu = (Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Environment' -Name PROCESSOR_ARCHITECTURE).PROCESSOR_ARCHITECTURE
	} else {
		# test seam: pwsh on Linux or macOS installs the Windows build into the home directory
		$cpu = [string][System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture
	}
	if ($cpu -match '^(AMD64|X64)$') {
		$arch = 'amd64'
	} elseif ($cpu -match '^ARM64$') {
		$arch = 'arm64'
	} else {
		Fail "unsupported architecture: $cpu"
	}
	$platform = "windows/$arch"
	if ($platforms -notcontains $platform) {
		if ($arch -eq 'arm64' -and $platforms -contains 'windows/amd64') {
			Write-Warn "no native ARM64 build of $name; installing the x64 build, which runs under emulation"
			$platform = 'windows/amd64'
		} else {
			Fail "no $name build for $platform"
		}
	}
	Write-Ok 'Detected' $platform

	# The platform's paths; run once without a version for the format and the checksums setting
	$ver = ''
	$tag = ''
	$assetPath = ''
	$format = ''
	$checksumsPath = ''
	$binaryInArchive = ''
	switch ($platform) {
		'windows/amd64' {
			$assetPath = ('download/' + $tag + '/my-cli_' + $ver + '_windows_amd64.zip')
			$format = 'zip'
			$checksumsPath = ('download/' + $tag + '/my-cli_' + $ver + '_checksums.txt')
			$binaryInArchive = ''
		}
		'windows/arm64' {
			$assetPath = ('download/' + $tag + '/my-cli_' + $ver + '_windows_arm64.zip')
			$format = 'zip'
			$checksumsPath = ('download/' + $tag + '/my-cli_' + $ver + '_checksums.txt')
			$binaryInArchive = ''
		}
	}

	try {
		[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
	} catch {
		Write-Verbose 'TLS 1.2 could not be enabled; using the defaults'
	}

	$tmp = Join-Path ([IO.Path]::GetTempPath()) ("$name-install-" + [Guid]::NewGuid().ToString('N'))
	New-Item -ItemType Directory -Path $tmp | Out-Null
	try {
		# Version: -Version, then <PREFIX>_VERSION, then the baked default, then the latest file
		$raw = $requested
		if (-not $raw) { $raw = $defaultVersion }
		$fromLatest = ''
		if ((-not $raw) -or $raw -eq 'latest') {
			$latestFile = Join-Path $tmp 'latest'
			try {
				Save-Url -Url $latestUrl -Path $latestFile -Label ''
			} catch {
				Fail "could not resolve the latest version from ${latestUrl}: $($_.Exception.Message)"
			}
			$raw = [IO.File]::ReadAllText($latestFile)
			$fromLatest = ' (latest)'
		}
		$ver = $raw -replace '\s', ''
		if ($tagPrefix -and $ver.StartsWith($tagPrefix, [StringComparison]::Ordinal)) { $ver = $ver.Substring($tagPrefix.Length) }
		if ($ver -cnotmatch '^[A-Za-z0-9._+-]+$') { Fail "invalid version: '$ver'" }
		$tag = $tagPrefix + $ver
		switch ($platform) {
		'windows/amd64' {
			$assetPath = ('download/' + $tag + '/my-cli_' + $ver + '_windows_amd64.zip')
			$format = 'zip'
			$checksumsPath = ('download/' + $tag + '/my-cli_' + $ver + '_checksums.txt')
			$binaryInArchive = ''
		}
		'windows/arm64' {
			$assetPath = ('download/' + $tag + '/my-cli_' + $ver + '_windows_arm64.zip')
			$format = 'zip'
			$checksumsPath = ('download/' + $tag + '/my-cli_' + $ver + '_checksums.txt')
			$binaryInArchive = ''
		}
		}
		Write-Ok 'Version' "$ver$fromLatest"

		# Download
		$assetUrl = "$baseUrl/$assetPath"
		$assetFile = $assetPath.Substring($assetPath.LastIndexOf('/') + 1)
		$download = Join-Path $tmp $assetFile
		try {
			Save-Url -Url $assetUrl -Path $download -Label $assetFile
		} catch {
			Fail "download failed: $assetUrl ($($_.Exception.Message))"
		}
		Write-Ok 'Download' $assetFile

		# Verify: `hash  file`, `hash *file`, BSD `SHA256 (file) = hash`, or a file holding one bare hash
		if ($checksumsPath) {
			$checksumsUrl = "$baseUrl/$checksumsPath"
			$sumsFile = Join-Path $tmp 'checksums'
			try {
				Save-Url -Url $checksumsUrl -Path $sumsFile -Label ''
			} catch {
				Fail "download failed: $checksumsUrl ($($_.Exception.Message))"
			}
			$lines = @([IO.File]::ReadAllLines($sumsFile) | Where-Object { $_.Trim() })
			$expected = ''
			foreach ($line in $lines) {
				$fields = @($line.Trim() -split '\s+')
				if ($fields.Count -ge 4 -and $fields[0] -ceq 'SHA256' -and $fields[1] -ceq "($assetFile)" -and $fields[2] -eq '=') {
					$expected = $fields[3]
					break
				}
				if ($fields.Count -ge 2 -and ($fields[1] -replace '^\*', '') -ceq $assetFile) {
					$expected = $fields[0]
					break
				}
			}
			if (-not $expected -and $lines.Count -eq 1 -and @($lines[0].Trim() -split '\s+').Count -eq 1) {
				$expected = $lines[0].Trim()
			}
			if (-not $expected) { Fail "no checksum for $assetFile in $checksumsUrl" }
			$expected = $expected.ToLowerInvariant()
			if ($expected -cnotmatch '^[0-9a-f]{64}$') { Fail "malformed checksum for $assetFile in $checksumsUrl" }
			$actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $download).Hash.ToLowerInvariant()
			if ($actual -ne $expected) { Fail "checksum mismatch for ${assetFile}: expected $expected, got $actual" }
			Write-Ok 'Verified' 'sha256'
		} else {
			Write-WarnRow 'Verified' 'skipped: no checksums published'
		}

		# Extract: tar.gz and zip both through bsdtar, which Windows ships as System32\tar.exe
		$exe = "$name.exe"
		$extracted = Join-Path $tmp 'x'
		if ($format -ne 'raw') {
			New-Item -ItemType Directory -Path $extracted | Out-Null
			$extractOk = $true
			if ($onWindows) {
				& (Join-Path $env:SystemRoot 'System32\tar.exe') -xf $download -C $extracted
				$extractOk = $LASTEXITCODE -eq 0
			} elseif ($format -eq 'zip') {
				# test seam: GNU tar cannot read zip. Expand-Archive is a script module, so it reads the global
				# preference, not this scope's.
				$savedProgress = $global:ProgressPreference
				$global:ProgressPreference = 'SilentlyContinue'
				try {
					Expand-Archive -LiteralPath $download -DestinationPath $extracted
				} finally {
					$global:ProgressPreference = $savedProgress
				}
			} else {
				& tar -xzf $download -C $extracted
				$extractOk = $LASTEXITCODE -eq 0
			}
			if (-not $extractOk) { Fail "could not extract $assetFile" }
		}
		if ($format -eq 'raw') {
			$bin = $download
		} elseif ($binaryInArchive) {
			$bin = Join-Path $extracted $binaryInArchive
		} else {
			# exactly one match: a mispacked archive with two must not install whichever comes first
			$hits = @(Get-ChildItem -LiteralPath $extracted -Recurse -File | Where-Object { $_.Name -eq $exe })
			if ($hits.Count -gt 1) { Fail "$assetFile holds $($hits.Count) files named $exe; set binaryInArchive" }
			$bin = if ($hits.Count -eq 1) { $hits[0].FullName } else { '' }
		}
		if ((-not $bin) -or -not (Test-Path -LiteralPath $bin -PathType Leaf)) { Fail "$exe not found in $assetFile" }

		# Install. A running exe cannot be overwritten or deleted, but it can be renamed: move it aside first.
		$found = Get-Command -CommandType Application -Name $exe -ErrorAction SilentlyContinue | Select-Object -First 1
		$target = Join-Path $installDir $exe
		$verb = if (Test-Path -LiteralPath $target) { 'Updated' } else { 'Installed' }
		New-Item -ItemType Directory -Force -Path $installDir | Out-Null
		if ($verb -eq 'Updated') {
			$old = "$target.old"
			if (Test-Path -LiteralPath $old) {
				try { Remove-Item -LiteralPath $old -Force } catch { $old = "$target.old-$PID" }
			}
			Move-Item -LiteralPath $target -Destination $old -Force
			try {
				Copy-Item -LiteralPath $bin -Destination $target
			} catch {
				Move-Item -LiteralPath $old -Destination $target -Force
				Fail "could not write ${target}: $($_.Exception.Message)"
			}
			try {
				Remove-Item -LiteralPath $old -Force
			} catch {
				Write-Verbose "$old is still in use; it goes on the next update"
			}
		} else {
			try {
				Copy-Item -LiteralPath $bin -Destination $target
			} catch {
				Fail "could not write ${target}: $($_.Exception.Message)"
			}
		}
		$targetShown = if ($dirShown -eq $installDir) { $target } else { "$dirShown\$exe" }
		Write-Ok $verb $targetShown
	} finally {
		Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
	}

	# PATH: the user PATH in the registry, read unexpanded and written back as REG_EXPAND_SZ
	$sep = [IO.Path]::PathSeparator
	$trim = [char[]]@('\', '/')
	$sameDir = { param($a, $b) $a.TrimEnd($trim) -eq $b.TrimEnd($trim) }
	$onPath = @($env:PATH -split [regex]::Escape([string]$sep) | Where-Object { $_ -and (& $sameDir $_ $installDir) }).Count -gt 0
	$pathChanged = $false
	if ($onPath) {
		Write-Ok 'PATH' 'already set'
	} elseif (-not $modifyPath) {
		Write-WarnRow 'PATH' "not changed; add $dirShown to PATH"
	} elseif (-not $onWindows) {
		Write-WarnRow 'PATH' 'not changed: the user PATH lives in the Windows registry'
	} else {
		$key = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Environment', $true)
		try {
			$userPath = [string]$key.GetValue('Path', '', [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
			$entries = @($userPath -split ';' | Where-Object { $_ })
			if (@($entries | Where-Object { & $sameDir $_ $installDir }).Count -eq 0) {
				$key.SetValue('Path', ((@($installDir) + $entries) -join ';'), [Microsoft.Win32.RegistryValueKind]::ExpandString)
				# a throwaway User variable set and cleared through .NET broadcasts WM_SETTINGCHANGE to Explorer
				[Environment]::SetEnvironmentVariable('INSTALLGEN_REFRESH', '1', 'User')
				[Environment]::SetEnvironmentVariable('INSTALLGEN_REFRESH', $null, 'User')
				Write-Ok 'PATH' 'added to the user PATH'
			} else {
				Write-Ok 'PATH' 'already in the user PATH'
			}
		} finally {
			$key.Close()
		}
		$env:PATH = "$installDir$sep$env:PATH"
		$pathChanged = $true
	}
	if ($modifyPath -and -not $onPath -and $env:GITHUB_PATH) {
		Add-Content -LiteralPath $env:GITHUB_PATH -Value $installDir
	}

	# Another copy shadows this one in new shells unless the user PATH now puts the install dir first. Windows
	# puts the machine PATH before the user PATH, so a copy there still wins.
	if ($found -and -not (& $sameDir $found.Path $target)) {
		$foundDir = Split-Path -Parent $found.Path
		$machine = @([string][Environment]::GetEnvironmentVariable('Path', 'Machine') -split ';' | Where-Object { $_ })
		if ((-not $pathChanged) -or @($machine | Where-Object { & $sameDir $_ $foundDir }).Count -gt 0) {
			Write-Warn "$($found.Path) comes first on PATH and shadows the new $name"
		}
	}

	Write-Host ''
	Write-Host "$name $ver $($verb.ToLowerInvariant())."
	if ($message) { Write-Host $message }
	if ($pathChanged) { Write-Host "Open a new terminal to use $name everywhere; this one is ready now." }
	Write-Host "To uninstall: Remove-Item '$($targetShown -replace "'", "''")'"
	Write-Host "To update: irm $ps1Url | iex"
	if ((-not $onWindows) -and $shUrl) { Write-Host "On Linux and macOS the native installer is: curl -fsSL $shUrl | sh" }
}
